-- migrations/172_phase197a_paper_caliper_and_livonia_reference.sql
-- PrintPrice OS — Phase 197A (SPINE-02): Paper Caliper Provenance & Livonia Technical Reference Staging
--
-- Strict Technical & Commercial Isolation Guarantees:
-- 1. Additive extension of paper_variants with caliper_um DECIMAL(8,2), bulk_factor, caliper_source,
--    caliper_confidence_status, caliper_verified_at, caliper_verified_by, and caliper_revision.
-- 2. Staging table paper_technical_caliper_reference containing all 60 blocks (375 gsm/micron pairs)
--    from Livonia Spine Calculator 2.0 ('Papers' sheet) without creating commercial offers or mutating
--    existing verified caliper values.
-- 3. Auditable reconciliation ledger paper_caliper_reconciliation_candidates separating SAFE_EXACT_MATCH,
--    AMBIGUOUS_MULTIPLE_BULK, CONFLICT_EXISTING_CALIPER, and UNMATCHED_IN_CATALOG.

-- 1. Extend paper_variants additively (preserving compatibility with existing 1,524 variants)
ALTER TABLE paper_variants
    MODIFY COLUMN caliper_um DECIMAL(8, 2) NULL,
    ADD COLUMN bulk_factor DECIMAL(6, 3) NULL AFTER caliper_mm,
    ADD COLUMN caliper_source ENUM('MEASURED_MICROMETER', 'MANUFACTURER_DATASHEET', 'LIVONIA_REFERENCE_IMPORT', 'SUPPLIER_IMPORT', 'BULK_DERIVED', 'NONE') NOT NULL DEFAULT 'NONE' AFTER bulk_factor,
    ADD COLUMN caliper_confidence_status ENUM('VERIFIED', 'REFERENCE_IMPORTED', 'PROVISIONAL_ESTIMATED', 'MISSING') NOT NULL DEFAULT 'MISSING' AFTER caliper_source,
    ADD COLUMN caliper_verified_at TIMESTAMP NULL AFTER caliper_confidence_status,
    ADD COLUMN caliper_verified_by VARCHAR(64) NULL AFTER caliper_verified_at,
    ADD COLUMN caliper_revision INT NOT NULL DEFAULT 1 AFTER caliper_verified_by;

-- 2. Livonia Technical Reference Library Staging Table (60 blocks, 375 gsm/caliper pairs)
CREATE TABLE IF NOT EXISTS paper_technical_caliper_reference (
    id VARCHAR(64) PRIMARY KEY,
    source_library VARCHAR(64) NOT NULL DEFAULT 'LIVONIA_SPINE_CALC_2_0',
    block_index INT NOT NULL,
    excel_header_coord VARCHAR(16) NOT NULL,
    excel_gsm_coord VARCHAR(16) NOT NULL,
    excel_microns_coord VARCHAR(16) NOT NULL,
    family_name VARCHAR(255) NOT NULL,
    normalized_family_key VARCHAR(255) NOT NULL,
    coating_raw VARCHAR(64) NOT NULL,
    canonical_category ENUM('CARTON', 'OFFSET', 'COATED', 'UNCOATED', 'DESIGN', 'DIGITAL', 'OTHER') NOT NULL,
    canonical_finish ENUM('COATED', 'UNCOATED', 'SILK') NOT NULL,
    declared_bulk DECIMAL(6, 3) NULL,
    gsm INT NOT NULL,
    caliper_um DECIMAL(8, 2) NOT NULL,
    caliper_mm DECIMAL(8, 4) NOT NULL,
    implied_bulk DECIMAL(6, 4) NOT NULL,
    is_multi_bulk_family BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_ptcr_family_gsm (normalized_family_key, gsm),
    INDEX idx_ptcr_category_gsm (canonical_category, gsm),
    UNIQUE KEY uk_ptcr_source_coord (source_library, excel_gsm_coord, excel_microns_coord)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Reconciliation Audit Table (Tracks candidate links between paper_variants and technical reference)
CREATE TABLE IF NOT EXISTS paper_caliper_reconciliation_candidates (
    id VARCHAR(64) PRIMARY KEY,
    variant_id VARCHAR(64) NOT NULL,
    product_id VARCHAR(64) NOT NULL,
    reference_id VARCHAR(64) NULL,
    reconciliation_status ENUM('SAFE_EXACT_MATCH', 'AMBIGUOUS_MULTIPLE_BULK', 'CONFLICT_EXISTING_CALIPER', 'UNMATCHED_IN_REFERENCE') NOT NULL,
    review_decision ENUM('PENDING_REVIEW', 'APPROVED', 'REJECTED') NOT NULL DEFAULT 'PENDING_REVIEW',
    existing_caliper_um DECIMAL(8, 2) NULL,
    proposed_caliper_um DECIMAL(8, 2) NULL,
    proposed_bulk_factor DECIMAL(6, 3) NULL,
    candidate_references_json JSON NULL,
    notes VARCHAR(512) NULL,
    reviewed_by VARCHAR(64) NULL,
    reviewed_at TIMESTAMP NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_pcrc_variant (variant_id),
    INDEX idx_pcrc_status (reconciliation_status, review_decision),
    CONSTRAINT fk_pcrc_variant FOREIGN KEY (variant_id) REFERENCES paper_variants(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

